/* the laser: bright core + soft additive glow + a reticle ring at the hit point */
function beamTex() { const c = document.createElement('canvas'); c.width = 64; c.height = 256; const g = c.getContext('2d'); const gr = g.createLinearGradient(0, 0, 64, 0); gr.addColorStop(0, 'rgba(255,255,255,0)'); gr.addColorStop(0.5, 'rgba(255,255,255,1)'); gr.addColorStop(1, 'rgba(255,255,255,0)'); g.fillStyle = gr; g.fillRect(0, 0, 64, 256); g.globalCompositeOperation = 'destination-in'; for (let y = 0; y < 256; y += 32) { const a = g.createLinearGradient(0, y, 0, y + 32); a.addColorStop(0, 'rgba(0,0,0,0.15)'); a.addColorStop(0.5, 'rgba(0,0,0,1)'); a.addColorStop(1, 'rgba(0,0,0,0.15)'); g.fillStyle = a; g.fillRect(0, y, 64, 32); } const t = new T.CanvasTexture(c); t.wrapS = t.wrapT = T.RepeatWrapping; return t; }
