  const ring2 = new T.Mesh(new T.TorusGeometry(0.56, 0.006, 8, 80), new T.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.6, depthTest: false })); ring2.renderOrder = 1001; portal.add(ring2);
  const glow = new T.Mesh(new T.RingGeometry(0.47, 0.78, 64), new T.MeshBasicMaterial({ color: accent, transparent: true, opacity: 0.3, blending: T.AdditiveBlending, depthTest: false, depthWrite: false, side: T.DoubleSide })); glow.renderOrder = 1001; portal.add(glow);
