  if (!wmTex) wmTex = makeTextTexture(tagline ? [name, tagline] : [name], { w: 1600, h: tagline ? 520 : 360, bg: 'rgba(0,0,0,0)', fg: '#ffffff', accent: hex, font: 'bold ' + (tagline ? 150 : 170) + 'px Poppins, Arial', glow: true, border: null, lineGap: 1.3 });
  const wm = new T.Mesh(new T.PlaneGeometry(0.84, tagline ? 0.273 : 0.19), new T.MeshBasicMaterial({ map: wmTex, transparent: true, opacity: 0, depthTest: false, depthWrite: false })); wm.renderOrder = 1002; wm.position.z = 0.03; portal.add(wm);
